import { useNavigate } from "react-router"
import logoTecHubPNG from "@/imports/LogoTecHubPNG.png"

const C = {
  bg: "#1b1c1e",
  card: "#242528",
  green: "#7ee753",
  greenDark: "#111213",
  textPrimary: "#FFFFFF",
  textSecondary: "#8A8F98",
}

export function HomePage() {
  const navigate = useNavigate()

  return (
    <main
      style={{
        backgroundColor: C.bg,
        minHeight: "calc(100vh - 60px)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
      }}
    >
      {/* Hero Section */}
      <section
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          textAlign: "center",
          padding: "48px 24px 5px",
          maxWidth: 860,
        }}
      >
        {/* Terminal Window Icon */}
        <img
          src={logoTecHubPNG}
          alt="TecHub terminal icon"
          style={{
            width: 200,
            height: "auto",
            marginBottom: 36,
            display: "block",
          }}
        />

        {/* <div style={{ width: 170, height: 135, backgroundColor: "#0e0f10", borderRadius: 16, overflow: "hidden", display: "flex", flexDirection: "column", marginBottom: 32, boxShadow: "0 10px 30px rgba(0,0,0,0.5)" }}>
          <div style={{ height: 28, display: "flex", alignItems: "center", gap: 7, paddingLeft: 14 }}>
            <span style={{ width: 9, height: 9, borderRadius: "50%", backgroundColor: "#e03e3e", display: "block" }} />
            <span style={{ width: 9, height: 9, borderRadius: "50%", backgroundColor: "#7ee753", display: "block" }} />
            <span style={{ width: 9, height: 9, borderRadius: "50%", backgroundColor: "#7ee753", display: "block" }} />
          </div>
          <div style={{ flex: 1, backgroundColor: "#202124", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <span style={{ color: C.green, fontSize: "3.2rem", fontWeight: 800, letterSpacing: "-2px", fontFamily: "monospace", userSelect: "none" }}>
              &lt;/&gt;
            </span>
          </div>
        </div> */}

        {/* Título Principal */}
        <h1
          style={{
            fontSize: "clamp(2rem, 3.8vw, 2.75rem)",
            fontWeight: 700,
            lineHeight: 1.22,
            letterSpacing: "-0.02em",
            color: C.textPrimary,
            margin: 0,
          }}
        >
          Mostre o que você sabe
          <br />
          construir, o mercado quer ver.
        </h1>

        {/* Subtítulo */}
        <p
          style={{
            color: C.textSecondary,
            fontSize: "1.05rem",
            lineHeight: 1.5,
            marginTop: 14,
            marginBottom: 28,
          }}
        >
          Conecte seus projetos a recrutadores,
          <br />
          através de um portfólio visual.
        </p>

        {/* CTA Buttons */}
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: 12,
            justifyContent: "center",
          }}
        >
          <button
            onClick={() => navigate("/projeto/novo")}
            style={{
              background: C.green,
              color: C.greenDark,
              border: "none",
              borderRadius: 8,
              padding: "10px 24px",
              fontSize: "0.9375rem",
              fontWeight: 600,
              cursor: "pointer",
              transition: "opacity 0.15s",
            }}
            onMouseEnter={(e) => (e.currentTarget.style.opacity = "0.88")}
            onMouseLeave={(e) => (e.currentTarget.style.opacity = "1")}
          >
            Publique seu projeto
          </button>

          <button
            style={{
              background: "#FFFFFF",
              color: "#111213",
              border: "none",
              borderRadius: 8,
              padding: "10px 24px",
              fontSize: "0.9375rem",
              fontWeight: 600,
              cursor: "pointer",
              transition: "opacity 0.15s",
            }}
            onMouseEnter={(e) => (e.currentTarget.style.opacity = "0.88")}
            onMouseLeave={(e) => (e.currentTarget.style.opacity = "1")}
          >
            Explore projetos
          </button>
        </div>
      </section>

      {/* Como Funciona Section */}
      <section
        style={{
          padding: "16px 24px 70px",
          width: "100%",
          maxWidth: 1040,
          boxSizing: "border-box",
        }}
      >
        <h2
          style={{
            textAlign: "center",
            fontSize: "1.75rem",
            fontWeight: 800,
            letterSpacing: "0.02em",
            color: C.textPrimary,
            marginBottom: 20,
          }}
        >
          COMO FUNCIONA
        </h2>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))",
            gap: 24,
          }}
        >
          <FeatureCard
            icon={<GraduationIcon />}
            title="Crie seu Portfólio"
            description="Cadastre seu perfil institucional e transforme seus aprendizados em portfólio real."
          />
          <FeatureCard
            icon={<CheckShieldIcon />}
            title="Projetos Checados"
            description="Os envios passam por uma moderação básica antes de ficarem visíveis na plataforma."
          />
          <FeatureCard
            icon={<RadarNetworkIcon />}
            title="Conexão e Vitrine"
            description="Publique, entre no radar e fique disponível para o contato de recrutadores da região."
          />
        </div>
      </section>
    </main>
  )
}

function FeatureCard({
  icon,
  title,
  description,
}: {
  icon: React.ReactNode
  title: string
  description: string
}) {
  return (
    <div
      style={{
        background: C.card,
        borderRadius: 14,
        padding: "36px 24px 32px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        textAlign: "center",
        minHeight: 250,
        boxSizing: "border-box",
      }}
    >
      <div
        style={{
          width: 78,
          height: 78,
          borderRadius: "50%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          marginBottom: 18,
        }}
      >
        {icon}
      </div>
      <h3
        style={{
          fontWeight: 700,
          fontSize: "1.1rem",
          color: C.textPrimary,
          margin: "0 0 10px 0",
        }}
      >
        {title}
      </h3>
      <p
        style={{
          color: C.textSecondary,
          fontSize: "0.9rem",
          lineHeight: 1.5,
          margin: 0,
          maxWidth: 240,
        }}
      >
        {description}
      </p>
    </div>
  )
}

